// ---------------------------------------------------------------------------
// Porta de entrada unica. Valida, normaliza e decide a acao.
//
// Tudo que chega do QS eh tratado como suspeito: campo faltando aqui vira
// resposta clara em vez de erro do Google 3 nos adiante.
// ---------------------------------------------------------------------------

// Troque por a ID da agenda dedicada (ex.: c_xxx@group.calendar.google.com).
// 'primary' joga tudo na agenda pessoal da conta da operacao.
const CALENDAR_PADRAO = 'primary';

const b = $input.first().json.body || {};
const acao = String(b.acao || 'criar').toLowerCase().trim();
const erros = [];

if (!b.meeting_id) erros.push('meeting_id ausente');
if (!['criar', 'reagendar', 'cancelar'].includes(acao)) erros.push('acao invalida: ' + acao);

if (acao === 'criar' || acao === 'reagendar') {
  if (!b.inicio) erros.push('inicio ausente');
  if (!b.fim) erros.push('fim ausente');
  if (b.inicio && b.fim && new Date(b.fim) <= new Date(b.inicio)) {
    erros.push('fim menor ou igual ao inicio');
  }
}
if (acao === 'reagendar' || acao === 'cancelar') {
  if (!b.event_id) erros.push('event_id ausente');
}

// E-mail malformado faz o Google recusar o evento INTEIRO com 400. Melhor
// descartar o convidado ruim e avisar o QS do que perder a reuniao.
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const brutos = (Array.isArray(b.convidados) ? b.convidados : [])
  .map((e) => String(e || '').trim())
  .filter(Boolean);
const convidados = brutos.filter((e) => EMAIL.test(e));
const descartados = brutos.filter((e) => !EMAIL.test(e));

// ID de evento deterministico: reenvio do mesmo meeting_id devolve 409 em vez
// de criar uma segunda reuniao. O Google so aceita base32hex (a-v e 0-9).
function idEvento(seed) {
  const alfa = 'abcdefghijklmnopqrstuv0123456789';
  const s = 'qs-' + String(seed);
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    out += alfa[c % 32] + alfa[(c >> 5) % 32];
  }
  return ('qs' + out).slice(0, 60);
}

return [{ json: {
  acao: erros.length ? 'invalida' : acao,
  erros,
  meeting_id: b.meeting_id ?? null,
  calendar_id: b.calendar_id || CALENDAR_PADRAO,
  event_id: b.event_id || null,
  event_id_previsto: b.meeting_id ? idEvento(b.meeting_id) : null,
  inicio: b.inicio || null,
  fim: b.fim || null,
  timezone: b.timezone || 'America/Sao_Paulo',
  titulo: b.titulo || 'Reuniao',
  descricao: b.descricao || '',
  convidados,
  convidados_descartados: descartados
} }];

// Corpo do evento do Google Calendar.
//
// conferenceData.createRequest eh o que faz o Google GERAR a sala do Meet. Sem
// o parametro conferenceDataVersion=1 na URL (no proximo no) o Google IGNORA
// este bloco em silencio: o evento nasce certinho, so que sem Meet nenhum.
//
// id deterministico + requestId estavel = reenvio devolve 409 e a MESMA sala,
// em vez de duplicar a reuniao.
const d = $json;

return [{ json: { ...d, evento: {
  id: d.event_id_previsto,
  summary: d.titulo,
  description: d.descricao,
  start: { dateTime: d.inicio, timeZone: d.timezone },
  end:   { dateTime: d.fim,   timeZone: d.timezone },
  attendees: d.convidados.map((email) => ({ email })),
  conferenceData: {
    createRequest: {
      requestId: 'qs-' + String(d.meeting_id),
      conferenceSolutionKey: { type: 'hangoutsMeet' }
    }
  },
  reminders: {
    useDefault: false,
    overrides: [ { method: 'popup', minutes: 30 }, { method: 'email', minutes: 60 } ]
  }
} } }];

// Resposta unica da acao criar. Serve tanto para insert novo quanto para o
// caminho do 409 (evento ja existia), porque os dois devolvem um Event.
//
// Nunca damos throw: o webhook responde 200 com ok:false e uma mensagem que se
// entende. Throw viraria 500 com stack trace e o QS perderia o motivo.
const r = $input.first().json;
const d = $('Validar entrada').first().json;
const status = r.statusCode;
const ev = r.body || {};

function motivo(body, st) {
  if (typeof body === 'string') return body.slice(0, 300);
  const e = body && body.error;
  if (typeof e === 'string') return e.slice(0, 300);
  if (e && (e.message || e.status)) return e.message || e.status;
  return 'HTTP ' + st;
}

if (status >= 400) {
  return [{ json: {
    ok: false,
    acao: 'criar',
    meeting_id: d.meeting_id,
    codigo: status,
    erro: motivo(ev, status)
  } }];
}

// hangoutLink eh o link do Meet. Se vier vazio, quase sempre falta o
// conferenceDataVersion=1 ou a conta nao tem permissao de criar conferencia.
// Devolvemos assim mesmo: o evento existe, o QS mostra a reuniao sem sala em
// vez de quebrar.
const pontos = (ev.conferenceData && ev.conferenceData.entryPoints) || [];
const meet = ev.hangoutLink
  || pontos.filter((p) => p.entryPointType === 'video').map((p) => p.uri)[0]
  || null;

return [{ json: {
  ok: true,
  acao: 'criar',
  meeting_id: d.meeting_id,
  calendar_id: d.calendar_id,
  event_id: ev.id || null,
  meet_link: meet,
  html_link: ev.htmlLink || null,
  sem_meet: !meet,
  duplicado: status === 409 || undefined,
  convidados_descartados: d.convidados_descartados
} }];

// PATCH so com o que muda. Nao reenviamos conferenceData: a sala do Meet eh
// preservada, entao o cliente que ja tem o link continua com o link certo.
const d = $json;

return [{ json: { ...d, patch: {
  summary: d.titulo,
  start: { dateTime: d.inicio, timeZone: d.timezone },
  end:   { dateTime: d.fim,   timeZone: d.timezone }
} } }];

const r = $input.first().json;
const d = $('Validar entrada').first().json;
const status = r.statusCode;
const ev = r.body || {};

function motivo(body, st) {
  if (typeof body === 'string') return body.slice(0, 300);
  const e = body && body.error;
  if (typeof e === 'string') return e.slice(0, 300);
  if (e && (e.message || e.status)) return e.message || e.status;
  return 'HTTP ' + st;
}

// 404/410 = o evento sumiu do Google (apagado na mao, por exemplo). Devolvemos
// codigo nao_encontrado para o QS reagir chamando acao=criar.
if (status === 404 || status === 410) {
  return [{ json: {
    ok: false,
    acao: 'reagendar',
    meeting_id: d.meeting_id,
    codigo: 'nao_encontrado',
    erro: 'evento nao existe mais no Google; recrie com acao=criar'
  } }];
}

if (status >= 400) {
  return [{ json: {
    ok: false,
    acao: 'reagendar',
    meeting_id: d.meeting_id,
    codigo: status,
    erro: motivo(ev, status)
  } }];
}

const pontos = (ev.conferenceData && ev.conferenceData.entryPoints) || [];
const meet = ev.hangoutLink
  || pontos.filter((p) => p.entryPointType === 'video').map((p) => p.uri)[0]
  || null;

return [{ json: {
  ok: true,
  acao: 'reagendar',
  meeting_id: d.meeting_id,
  calendar_id: d.calendar_id,
  event_id: ev.id || d.event_id,
  meet_link: meet,
  html_link: ev.htmlLink || null,
  inicio: d.inicio,
  fim: d.fim
} }];

const r = $input.first().json;
const d = $('Validar entrada').first().json;
const status = r.statusCode;

function motivo(body, st) {
  if (typeof body === 'string') return body.slice(0, 300);
  const e = body && body.error;
  if (typeof e === 'string') return e.slice(0, 300);
  if (e && (e.message || e.status)) return e.message || e.status;
  return 'HTTP ' + st;
}

// Cancelar eh idempotente: sucesso, ja apagado ou nunca existiu dao no mesmo.
const apagado = status === 204 || status === 200 || status === 404 || status === 410;

if (!apagado) {
  return [{ json: {
    ok: false,
    acao: 'cancelar',
    meeting_id: d.meeting_id,
    codigo: status,
    erro: motivo(r.body, status)
  } }];
}

return [{ json: {
  ok: true,
  acao: 'cancelar',
  meeting_id: d.meeting_id,
  event_id: d.event_id,
  ja_estava_apagado: status === 404 || status === 410 || undefined
} }];

// Payload invalido nunca chega no Google. Responde 200 com ok:false e a lista
// de erros, que eh o suficiente para o dev do QS achar o problema sem abrir log.
const d = $json;

return [{ json: {
  ok: false,
  acao: 'invalida',
  meeting_id: d.meeting_id,
  codigo: 'payload_invalido',
  erro: (d.erros || []).join('; ') || 'payload invalido'
} }];
